use super::types::{Path64, Point64};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct Rect64 {
    pub left: i64,
    pub top: i64,
    pub right: i64,
    pub bottom: i64,
}

impl Rect64 {
    pub fn from_path(path: &Path64) -> Option<Self> {
        if path.len() != 4 {
            return None;
        }

        let mut xs = [path[0].x, path[1].x, path[2].x, path[3].x];
        let mut ys = [path[0].y, path[1].y, path[2].y, path[3].y];
        xs.sort_unstable();
        ys.sort_unstable();

        if xs[0] == xs[3] || ys[0] == ys[3] {
            return None;
        }

        let left = xs[0];
        let right = xs[3];
        let top = ys[0];
        let bottom = ys[3];

        let corners = [
            Point64::new(left, top),
            Point64::new(right, top),
            Point64::new(right, bottom),
            Point64::new(left, bottom),
        ];

        if path.iter().all(|point| corners.contains(point)) {
            Some(Self {
                left,
                top,
                right,
                bottom,
            })
        } else {
            None
        }
    }

    pub const fn intersects(self, other: Self) -> bool {
        self.left < other.right
            && other.left < self.right
            && self.top < other.bottom
            && other.top < self.bottom
    }

    pub const fn intersection(self, other: Self) -> Option<Self> {
        let left = if self.left > other.left {
            self.left
        } else {
            other.left
        };
        let top = if self.top > other.top {
            self.top
        } else {
            other.top
        };
        let right = if self.right < other.right {
            self.right
        } else {
